Link: https://patch.msgid.link/20260422161438.2593376-5-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The `rxrpc_process_event` function in `conn_event.c` directly calls the security handler's `verify_response` on the received sk_buff, which performs in-place decryption. If the sk_buff is cloned (e.g., shared with a packet sniffer), the decryption modifies the shared buffer, causing the sniffer to see a corrupted (decrypted) packet instead of the original encrypted data. The code does not check for cloned skbs and does not create an unshared copy before calling the security handler.

Here is the patch:

+static int rxrpc_verify_response(struct rxrpc_connection *conn,
+				 struct sk_buff *skb)
+{
+	int ret;
+
+	if (skb_cloned(skb)) {
+		/* Copy the packet if shared so that we can do in-place
+		 * decryption.
+		 */
+		struct sk_buff *nskb = skb_copy(skb, GFP_NOFS);
+
+		if (nskb) {
+			rxrpc_new_skb(nskb, rxrpc_skb_new_unshared);
+			ret = conn->security->verify_response(conn, nskb);
+			rxrpc_free_skb(nskb, rxrpc_skb_put_response_copy);
+		} else {
+			/* OOM - Drop the packet. */
+			rxrpc_see_skb(skb, rxrpc_skb_see_unshare_nomem);
+			ret = -ENOMEM;
+		}
+	} else {
+		ret = conn->security->verify_response(conn, skb);
+	}
+
+	return ret;
+}
+
 /*
  * connection-level Rx packet processor
  */
 static int rxrpc_process_event(struct rxrpc_connection *conn,
 			       struct sk_buff *skb)
 {
 	struct rxrpc_skb_priv *sp = rxrpc_skb(skb);
 	bool secured = false;
 	int ret;

 	if (conn->state == RXRPC_CONN_ABORTED)
 		return -ECONNABORTED;

 	_enter("{%d},{%u,%%%u},", conn->debug_id, sp->hdr.type, sp->hdr.serial);

 	switch (sp->hdr.type) {
 	case RXRPC_PACKET_TYPE_CHALLENGE:
 		ret = conn->security->respond_to_challenge(conn, skb);
 		sp->chall.conn = NULL;
 		rxrpc_put_connection(conn, rxrpc_conn_put_challenge_input);
 		return ret;

 	case RXRPC_PACKET_TYPE_RESPONSE:
 		spin_lock_irq(&conn->state_lock);
 		if (conn->state != RXRPC_CONN_SERVICE_CHALLENGING) {
 			spin_unlock_irq(&conn->state_lock);
 			return 0;
 		}
 		spin_unlock_irq(&conn->state_lock);

-		ret = conn->security->verify_response(conn, skb);
+		ret = rxrpc_verify_response(conn, skb);
 		if (ret < 0)
 			return ret;

 		ret = conn->security->init_connection_security(
 			conn, conn->key->payload.data[0]);
 		if (ret < 0)
 			return ret;

 		spin_lock_irq(&conn->state_lock);
 		if (conn->state == RXRPC_CONN_SERVICE_CHALLENGING) {
 			conn->state = RXRPC_CONN_SERVICE;
 			secured = true;
 		}
 		spin_unlock_irq(&conn->state_lock);

 		if (secured) {
 			/* Offload call state flipping to the I/O thread.  As
 			 * we've already received the packet, put it on the
 			 * front of the queue.
 			 */
 			sp->poke_conn = rxrpc_get_connection(
 				conn, rxrpc_conn_get_poke_secured);
 			skb->mark = RXRPC_SKB_MARK_SERVICE_CONN_SECURED;
 			rxrpc_get_skb(skb, rxrpc_skb_get_conn_secured);
 			skb_queue_head(&conn->local->rx_queue, skb);
 			rxrpc_wake_up_io_thread(conn->local);
 		}
 		return 0;

 	default:
 		WARN_ON_ONCE(1);
 		return -EPROTO;
 	}
 }



